import{_ as e,o as d,c as o,a2 as a}from"./chunks/framework.CZqXuAiL.js";const f=JSON.parse(`{"title":"Configuration Reference","description":"Every Panel Firewall setting — panel admin settings and the daemon's /etc/panel-firewall/config.json — with types, defaults, and when to change them.","frontmatter":{"title":"Configuration Reference","description":"Every Panel Firewall setting — panel admin settings and the daemon's /etc/panel-firewall/config.json — with types, defaults, and when to change them."},"headers":[],"relativePath":"panel-firewall/configuration/reference.md","filePath":"panel-firewall/configuration/reference.md","lastUpdated":null}`),r={name:"panel-firewall/configuration/reference.md"};function n(c,t,i,l,s,h){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="configuration-reference" tabindex="-1">Configuration Reference <a class="header-anchor" href="#configuration-reference" aria-label="Permalink to &quot;Configuration Reference&quot;">​</a></h1><p>Panel Firewall is configured in two places: the <strong>admin UI</strong> (stored in the panel DB, pushed to the daemon on apply) and the daemon&#39;s local <strong><code>/etc/panel-firewall/config.json</code></strong> (written once by the installer — rarely touched afterwards).</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Settings changed in the admin UI only reach the kernel after <strong>Apply firewall</strong>. The apply payload is the single source of truth — the daemon reloads it on every 5-second tick.</p></div><hr><h2 id="panel-settings-admin-→-panel-firewall-→-settings-firewall" tabindex="-1">Panel settings (Admin → Panel Firewall → Settings / Firewall) <a class="header-anchor" href="#panel-settings-admin-→-panel-firewall-→-settings-firewall" aria-label="Permalink to &quot;Panel settings (Admin → Panel Firewall → Settings / Firewall)&quot;">​</a></h2><h3 id="core" tabindex="-1">Core <a class="header-anchor" href="#core" aria-label="Permalink to &quot;Core&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>daemon_url</code></td><td>URL</td><td><code>http://127.0.0.1:8475</code></td><td>Where the panel reaches the daemon. Must be <code>http(s)://</code>, no credentials/query. Change only if the daemon listens elsewhere.</td></tr><tr><td><code>http_port</code></td><td>int 1–65535</td><td><code>80</code></td><td>Panel HTTP port to protect (jump target for firewall chains).</td></tr><tr><td><code>https_port</code></td><td>int 1–65535</td><td><code>443</code></td><td>Panel HTTPS port to protect.</td></tr><tr><td><code>preset</code></td><td>enum</td><td><code>medium</code></td><td>Traffic ceiling profile: <code>low</code>, <code>medium</code>, <code>high</code>, <code>veryHigh</code>, <code>underAttack</code>. See <a href="./../architecture/protection-layers#presets">Protection Layers</a>.</td></tr><tr><td><code>global_enabled</code></td><td>bool</td><td><code>false</code></td><td>Master switch. When off, the daemon keeps chains empty (traffic untouched).</td></tr><tr><td><code>smart_enabled</code></td><td>bool</td><td><code>false</code></td><td>Enables the EWMA anomaly detector + L1–L3 auto-mitigation.</td></tr><tr><td><code>smart.alpha</code></td><td>float 0.001–1</td><td><code>0.1</code></td><td>EWMA smoothing for the metric mean. Higher = reacts faster, noisier.</td></tr><tr><td><code>smart.beta</code></td><td>float 0.001–1</td><td><code>0.05</code></td><td>EWMA smoothing for the variance estimate.</td></tr><tr><td><code>smart.anomalyDeviation</code></td><td>float 1–20</td><td><code>4</code></td><td>Anomaly threshold in standard deviations above baseline. Raise if you get false positives.</td></tr></tbody></table><h3 id="whitelist-blacklist-lists-page" tabindex="-1">Whitelist / blacklist (Lists page) <a class="header-anchor" href="#whitelist-blacklist-lists-page" aria-label="Permalink to &quot;Whitelist / blacklist (Lists page)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>List</th><th>Behavior</th></tr></thead><tbody><tr><td>Whitelist (<code>adminWhitelist</code>)</td><td>CIDRs accepted <strong>before any other rule</strong> — these IPs can never be rate-limited or banned. Add your office/static IP here first. Strict CIDR validation (no <code>999.1.1.1</code>, no leading zeros).</td></tr><tr><td>Permanent blacklist (<code>permanentBlacklist</code>)</td><td>CIDRs dropped at the top of the chain, before rate limits.</td></tr><tr><td>Temporary bans</td><td>Created by admins, SMART, or the L7 sensor; expire automatically.</td></tr></tbody></table><h3 id="l7-http-flood-protection-settings-page" tabindex="-1">L7 HTTP flood protection (Settings page) <a class="header-anchor" href="#l7-http-flood-protection-settings-page" aria-label="Permalink to &quot;L7 HTTP flood protection (Settings page)&quot;">​</a></h3><p>All keys emit into the apply payload&#39;s <code>l7</code> block; the daemon sensor reads the web server access log — <strong>no nginx/apache config changes needed</strong>.</p><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>l7_enabled</code></td><td>bool</td><td><code>false</code></td><td>Master switch for the access-log sensor.</td></tr><tr><td><code>l7_log_paths</code></td><td>text, one per line</td><td><em>(empty)</em></td><td>Log files to tail. Empty = autodetect: <code>/var/log/nginx/access.log</code>, <code>/var/log/apache2/access.log</code>, <code>/var/log/httpd/access_log</code>, <code>/var/log/caddy/access.log</code>. Max 16 paths × 256 chars.</td></tr><tr><td><code>l7_rate_limit_rpm</code></td><td>int 10–100000</td><td><code>600</code></td><td>Per-IP requests-per-window ceiling. Exceeding it = offense.</td></tr><tr><td><code>l7_window_sec</code></td><td>int 5–3600</td><td><code>60</code></td><td>Sliding window length in seconds. Offense = <code>count &gt; rateLimitRpm × windowSec/60</code>.</td></tr><tr><td><code>l7_ban_duration_sec</code></td><td>int 60–86400</td><td><code>900</code></td><td>Temp-ban lifetime (15 min default).</td></tr><tr><td><code>l7_exclude_private</code></td><td>bool</td><td><code>true</code></td><td>Never ban private/reserved IPs (10/8, 172.16/12, 192.168/16, loopback, link-local, CGNAT, IPv6 ULA). Keep on if admins use internal IPs.</td></tr><tr><td><code>l7_max_bans_per_minute</code></td><td>int 1–1000</td><td><code>20</code></td><td>Budget cap so a log flood can&#39;t churn the ban ipset. Overflow is counted, not banned.</td></tr></tbody></table><h3 id="webhooks" tabindex="-1">Webhooks <a class="header-anchor" href="#webhooks" aria-label="Permalink to &quot;Webhooks&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Notes</th></tr></thead><tbody><tr><td><code>url</code></td><td><strong>HTTPS only, public IPs only</strong> — DNS is fully resolved and the validated IP is pinned for the request (SSRF/DNS-rebinding protection). Private/loopback/metadata addresses are rejected.</td></tr><tr><td><code>events</code></td><td>Subset of the event list (see <a href="./../user-guide/webhooks">Webhooks</a>).</td></tr><tr><td><code>secret</code></td><td>Optional HMAC secret signing webhook payloads. Never exported — export bundles show <code>[REDACTED]</code>.</td></tr></tbody></table><hr><h2 id="daemon-config-—-etc-panel-firewall-config-json" tabindex="-1">Daemon config — <code>/etc/panel-firewall/config.json</code> <a class="header-anchor" href="#daemon-config-—-etc-panel-firewall-config-json" aria-label="Permalink to &quot;Daemon config — `/etc/panel-firewall/config.json`&quot;">​</a></h2><p>Written by the installer. Re-runs <strong>preserve</strong> it (<code>PFW_FORCE_CONFIG=1</code> regenerates). Restart the service after edits: <code>systemctl restart panel-firewall</code>.</p><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Default</th><th>What it does / when to change</th></tr></thead><tbody><tr><td><code>listenAddress</code></td><td>IP/<code>localhost</code></td><td><code>127.0.0.1</code></td><td>Bind address. Keep loopback unless the panel is on another host. Must be a valid IP — anything else refuses to start.</td></tr><tr><td><code>listenPort</code></td><td>int</td><td><code>8475</code></td><td>API port. Change if 8475 collides; then update <code>daemon_url</code> in the panel.</td></tr><tr><td><code>allowedIps</code></td><td>CIDR[]</td><td><code>[&quot;127.0.0.1&quot;]</code></td><td>IP allowlist (layer 1 of auth). Empty + non-loopback bind <strong>refuses to start</strong> unless <code>allowEmptyAllowlist: true</code>.</td></tr><tr><td><code>allowEmptyAllowlist</code></td><td>bool</td><td><code>false</code></td><td>Explicit opt-in to run with no IP allowlist. Avoid.</td></tr><tr><td><code>trustProxy</code></td><td>bool</td><td><code>false</code></td><td>Trust <code>X-Forwarded-For</code> for <code>request.ip</code>. Only enable behind a real reverse proxy — otherwise the allowlist is spoofable.</td></tr><tr><td><code>protectedPorts</code></td><td>object</td><td><code>{http: 80, https: 443}</code></td><td>Ports the firewall chains hook.</td></tr><tr><td><code>confirm.confirmWindowSec</code></td><td>int 15–300</td><td><code>60</code></td><td>Auto-rollback window after each apply.</td></tr><tr><td><code>confirm.confirmDelaySec</code></td><td>int 0–60</td><td><code>10</code></td><td>Delay before the confirm button unlocks (gives you time to notice breakage).</td></tr><tr><td><code>security.timestampDriftSec</code></td><td>int 10–300</td><td><code>60</code></td><td>Max clock skew accepted for HMAC timestamps.</td></tr><tr><td><code>preset</code></td><td>enum</td><td><code>medium</code></td><td>Startup preset (panel apply overrides).</td></tr><tr><td><code>smart</code></td><td>object</td><td><code>{enabled:false, alpha:0.1, beta:0.05, anomalyDeviation:4}</code></td><td>Startup SMART defaults (panel apply overrides).</td></tr><tr><td><code>l7</code></td><td>object</td><td><code>{enabled:false, logPaths:[], rateLimitRpm:600, windowSec:60, banDurationSec:900, excludePrivate:true, maxBansPerMinute:20}</code></td><td>Startup L7 defaults (panel apply overrides).</td></tr><tr><td><code>reconcile</code></td><td>object</td><td><code>{enabled:true, intervalSec:60, autoRepair:true}</code></td><td>Kernel-vs-desired drift checker.</td></tr><tr><td><code>logLevel</code></td><td>enum</td><td><code>info</code></td><td><code>debug</code>/<code>info</code>/<code>warn</code>/<code>error</code>/<code>fatal</code>.</td></tr><tr><td><code>devMode.skipIptables</code></td><td>bool</td><td><code>false</code></td><td>Test mode: no kernel mutation. Never use in production.</td></tr></tbody></table><h2 id="environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment variables&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Var</th><th>Purpose</th></tr></thead><tbody><tr><td><code>PFW_CONFIG</code></td><td>Config file path (default <code>/etc/panel-firewall/config.json</code>)</td></tr><tr><td><code>PFW_TOKEN</code></td><td>Token file path (default <code>/etc/panel-firewall/token</code>)</td></tr><tr><td><code>PFW_STATE_DIR</code></td><td>SQLite + checkpoints dir (default <code>/var/lib/panel-firewall</code>)</td></tr><tr><td><code>PFW_SKIP_IPTABLES=1</code></td><td>Dev mode without touching config</td></tr><tr><td><code>PFW_SKIP_EXT_CHECK=1</code></td><td>Skip the installer&#39;s PHP-extension preflight</td></tr><tr><td><code>PFW_SKIP_DAEMON_UNINSTALL=1</code></td><td><code>remove.sh</code> keeps the daemon installed</td></tr></tbody></table><hr><h2 id="common-mistakes" tabindex="-1">Common mistakes <a class="header-anchor" href="#common-mistakes" aria-label="Permalink to &quot;Common mistakes&quot;">​</a></h2><ul><li><strong>Forgetting Apply after changing settings</strong> — the panel DB is not live state; only an apply pushes config to the kernel.</li><li><strong>Whitelisting nothing, then tuning aggressively</strong> — add your own IP to the whitelist <em>before</em> switching to <code>high</code>/<code>underAttack</code>.</li><li><strong>Setting <code>l7_rate_limit_rpm</code> too low</strong> — admin panel traffic is bursty (asset loads, websockets). Start at 600+, watch the analytics graph, then tighten.</li><li><strong>Pointing <code>daemon_url</code> at a public interface</strong> — keep the daemon on loopback; its only real barrier on a public bind is the bearer token.</li></ul>',23)])])}const g=e(r,[["render",n]]);export{f as __pageData,g as default};
